def load_builtin_font(size):
    """从内置 base64 数据解压字体并加载（内存加载，无需临时文件）。"""
    try:
        font_data = gzip.decompress(base64.b64decode("".join(FONT_B64.split())))
        return ImageFont.truetype(BytesIO(font_data), size)
    except Exception:
        return None


# ================== 基础配置读取 ==================

def config(key, default=""):
    return str(middleware.bucketGet(BUCKET, key) or default).strip()


def config_int(key, default):
    try:
        return int(config(key, default))
    except ValueError:
        return default


# ================== 插件元数据解析（复用 v2 成熟逻辑） ==================

def meta_values(text, key):
    pattern = rf"^#\s*\[{re.escape(key)}\s*:\s*(.*)\]\s*.*$"
    return [item.strip() for item in re.findall(pattern, text, re.M | re.I) if item.strip()]


def meta_value(text, key):
    values = meta_values(text, key)
    return values[0] if values else ""


def script_text(raw):
    if raw in (None, ""):
        return ""
    text = str(raw)
    try:
        data = json.loads(text)
    except (TypeError, ValueError):
        return text
    if isinstance(data, str):
        return data
    if isinstance(data, dict):
        for key in ("content", "script", "code", "source", "data"):
            value = data.get(key)
            if isinstance(value, str) and value:
                return value
    return text


def read_bucket_script(key):
    try:
        return script_text(middleware.bucketGet(SCRIPT_BUCKET, key))
    except Exception:
        return ""


def split_alternatives(value):
    parts, start, depth = [], 0, 0
    for index, char in enumerate(value):
        if char == "(":
            depth += 1
        elif char == ")":
            depth -= 1
        elif char == "|" and depth == 0:
            parts.append(value[start:index]); start = index + 1
    parts.append(value[start:])
    return parts


def expand_expression(value):
    branches = split_alternatives(value)
    if len(branches) > 1:
        result = []
        for branch in branches:
            result.extend(expand_expression(branch.removeprefix("^").removesuffix("$")))
        return result
    results, index = [""], 0
    while index < len(value):
        if value[index] == "(":
            depth, end = 1, index + 1
            while end < len(value) and depth:
                depth += (value[end] == "(") - (value[end] == ")")
                end += 1
            if depth:
                return []
            inner = value[index + 1:end - 1]
            choices = [" … "] if inner in (".*", ".+") else expand_expression(inner)
            if not choices:
                return []
            results = [prefix + choice for prefix in results for choice in choices]
            index = end
            continue
        if value.startswith((".*", ".+"), index):
            results = [prefix + " … " for prefix in results]
            index += 2
            continue
        char = value[index]
        if char in "^$":
            index += 1
            continue
        if char == "\\" or char in "[]{}?+*":
            return []
        results = [prefix + char for prefix in results]
        index += 1
    return results


def simple_commands(rule):
    value = rule.strip().replace("(?:", "(")
    if not value or "http" in value.lower() or "\\." in value:
        return []
    commands = expand_expression(value)
    return list(dict.fromkeys(" ".join(item.split()) for item in commands if item.strip()))[:50]


def description_commands(description):
    match = re.search(r"指令[：:]\s*([^。；<]+)", description)
    if not match:
        return []
    values = re.split(r"[、，,\s]+", match.group(1).strip())
    return [item for item in values if item and len(item) <= 20]


def is_auto_rule(rule):
    lowered = rule.lower()
    return any(mark in lowered for mark in ("http://", "https://", "https?://", "cq:image", "cq:video"))


def rule_commands(rule):
    commands = simple_commands(rule)
    if commands:
        return commands
    value = rule.removeprefix("^").lstrip("(")
    match = re.match(r"([\u4e00-\u9fffA-Za-z0-9_-]{2,})", value)
    return [match.group(1) + " …"] if match else []


def plugin_info(key, source):
    header = "\n".join(source.splitlines()[:HEADER_LIMIT])
    title = meta_value(header, "title") or str(key).rsplit("/", 1)[-1].removesuffix(".py")
    if title == "菜单":
        return None
    hidden = {x.strip() for x in re.split(r"[,，]", config("hidden")) if x.strip()}
    if title in hidden or meta_value(header, "menu_hidden").lower() == "true":
        return None
    rules = meta_values(header, "rule")
    visible_rules = [rule for rule in rules if not is_auto_rule(rule)]
    description = meta_value(header, "description")
    commands = []
    for rule in visible_rules:
        commands.extend(rule_commands(rule))
    commands = list(dict.fromkeys(commands or description_commands(description)))[:30]
    if not rules or not visible_rules:
        return None
    try:
        order = int(meta_value(header, "menu_order") or "100")
    except ValueError:
        order = 100
    return {"title": title, "commands": commands, "order": order}


def read_file_script(path):
    try:
        return path.read_text(encoding="utf-8-sig", errors="ignore")
    except OSError:
        return ""


def plugin_directories():
    values = []
    if "__file__" in globals():
        values.append(Path(__file__).resolve().parent)
    values.append(Path(os.getcwd()))
    custom = config("plugin_dir")
    if custom:
        values.append(Path(custom).expanduser())
    values.append(Path("/root/yuhua-panel/data/plugins"))
    result = []
    for path in values:
        try:
            resolved = path.resolve()
        except OSError:
            continue
        if resolved.is_dir() and resolved not in result:
            result.append(resolved)
    return result


def merge_plugin(target, info):
    if not info:
        return
    title = info["title"]
    if title not in target:
        target[title] = info
        return
    old = target[title]
    old["commands"] = list(dict.fromkeys(old["commands"] + info["commands"]))[:50]
    old["order"] = min(old["order"], info["order"])


def scan_plugins():
    found = {}
    try:
        keys = middleware.bucketAllKeys(SCRIPT_BUCKET) or []
    except Exception:
        keys = []
    for key in keys:
        source = read_bucket_script(key)
        if source:
            merge_plugin(found, plugin_info(key, source))
    for directory in plugin_directories():
        for path in directory.glob("*.py"):
            source = read_file_script(path)
            if source:
                merge_plugin(found, plugin_info(path.name, source))
    return sorted(found.values(), key=lambda item: (item["order"], item["title"]))


# ================== 字体加载（v5.1 内置字体，零配置） ==================
# 加载优先级：
#   1) 配置项 auto_menu.font_path（用户显式指定）
#   2) 系统常见中文字体（自动探测，容器里恰好有就用更丰富的）
#   3) 内置字体（gzip+base64 内存解压，GB2312 全字集）—— 默认路径，无需任何外部文件
#   4) Pillow 默认字体（理论上的最后兜底）

CJK_FONT_MARKS = ("wqy", "microhei", "zenhei", "noto", "cjk", "uming", "droid",
                  "source", "yahei", "msyh", "simhei", "simsun", "pingfang",
                  "heiti", "songti", "kai", "fangsong", "sanscjk", "sarasa")
FONT_SUFFIXES = (".ttc", ".ttf", ".otf")

FONT_CANDIDATES = [
    "/data/fonts/wqy-microhei.ttc",
    "/data/fonts/wqy-zenhei.ttc",
    "/data/fonts/msyh.ttc",
    "/data/fonts/msyh.ttf",
    "/data/fonts/NotoSansCJK-Regular.ttc",
    "/data/fonts/NotoSansCJKsc-Regular.otf",
    "/data/fonts/sarasa-gothic.ttc",
    "/root/yuhua-panel/data/fonts/wqy-microhei.ttc",
    "/usr/share/fonts/truetype/wqy/wqy-microhei.ttc",
    "/usr/share/fonts/truetype/wqy/wqy-zenhei.ttc",
    "/usr/share/fonts/truetype/arphic/uming.ttc",
    "/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc",
    "/usr/share/fonts/noto-cjk/NotoSansCJK-Regular.ttc",
    "/usr/share/fonts/truetype/droid/DroidSansFallbackFull.ttf",
    "C:\\Windows\\Fonts\\msyh.ttc",
    "C:\\Windows\\Fonts\\msyh.ttf",
    "C:\\Windows\\Fonts\\simhei.ttf",
    "C:\\Windows\\Fonts\\simsun.ttc",
]

FONT_SCAN_ROOTS = [
    "/data/fonts",
    "/root/yuhua-panel/data/fonts",
    "/usr/share/fonts",
    "/usr/local/share/fonts",
    "C:\\Windows\\Fonts",
]


def _is_cjk_font(path):
    name = Path(path).name.lower()
    return any(mark in name for mark in CJK_FONT_MARKS)


def _font_collect():
    seen, fonts = set(), []

    def add(path):
        p = Path(path)
        if p.is_file() and str(p) not in seen:
            seen.add(str(p))
            fonts.append(p)

    custom = config("font_path")
    if custom:
        add(custom)
    for path in FONT_CANDIDATES:
        if _is_cjk_font(path):
            add(path)
    for root in FONT_SCAN_ROOTS:
        base = Path(root)
        if not base.is_dir():
            continue
        try:
            files = sorted(base.rglob("*"))
        except OSError:
            continue
        for f in files:
            if f.is_file() and f.suffix.lower() in FONT_SUFFIXES and _is_cjk_font(f.name):
                add(f)
    return fonts


def get_best_font(size):
    # 1) 配置路径 + 系统探测
    for path in _font_collect():
        try:
            return ImageFont.truetype(str(path), size, index=0)
        except Exception:
            continue
    # 2) 内置字体（零配置兜底，正常情况都会走到这里）
    builtin = load_builtin_font(size)
    if builtin is not None:
        return builtin
    # 3) 最后兜底
    return ImageFont.load_default()


# ================== 卡片绘图（v5.2 极简卡片风） ==================
# 参考图风格：白底圆角+浅描边+噪点背景+emoji图标+等宽标题+无色块序号。
# emoji 用系统字体（Segoe UI Emoji / Noto Color Emoji / Apple Color Emoji），
# 没有就降级为内置字体的符号（▫ ★ ▶ → 等），不出现豆腐块。

import random as _random
_random.seed(42)  # 噪点/装饰随机确定，避免每次重新请求长得不一样

# 配色（极简、扁平、近似 iOS 卡片）
BG          = (245, 246, 248)        # 画布底色（浅灰）
BG_NOISE_A  = (228, 230, 236)        # 噪点颜色（极淡）
BG_NOISE_B  = (220, 222, 230)
CARD_FILL   = (255, 255, 255)        # 卡片白底
CARD_LINE   = (226, 227, 232)        # 极浅描边
ROW_DIVIDER = (240, 240, 243)        # 行间分隔线
TITLE_TXT   = (26, 26, 26)           # 主标题深色
SUB_TXT     = (142, 142, 147)        # 副标题灰
BODY_TXT    = (38, 38, 38)           # 行标题深色
COUNT_TXT   = (155, 158, 163)        # 右侧小字灰
EQ_TXT      = (180, 184, 192)        # "====="等号线颜色
FOOT_TXT    = (170, 172, 178)        # 底部脚注

# emoji 字体候选路径（系统探测，没有就降级符号，不内嵌以免文件爆炸）
EMOJI_FONT_CANDIDATES = [
    "C:\\Windows\\Fonts\\seguiemj.ttf",           # Windows: Segoe UI Emoji (彩色)
    "C:\\Windows\\Fonts\\seguisym.ttf",           # Windows: Segoe UI Symbol
    "/System/Library/Fonts/Apple Color Emoji.ttc",     # macOS
    "/usr/share/fonts/truetype/noto/NotoColorEmoji.ttf",  # Linux: Noto Color Emoji
    "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", # Linux fallback
    "/usr/share/fonts/truetype/ancient-scripts/Symbola.ttf",  # Linux Symbola
]
_EMOJI_FONT_PATH_CACHE = None


def _emoji_font_path():
    """探测系统 emoji/符号字体；返回路径或 None。"""
    global _EMOJI_FONT_PATH_CACHE
    if _EMOJI_FONT_PATH_CACHE is not None:
        return _EMOJI_FONT_PATH_CACHE
    for p in EMOJI_FONT_CANDIDATES:
        if Path(p).is_file():
            _EMOJI_FONT_PATH_CACHE = p
            return p
    _EMOJI_FONT_PATH_CACHE = False
    return None


def _emoji_font(size):
    """加载系统 emoji 字体；失败返回 None（调用方降级符号）。"""
    p = _emoji_font_path()
    if not p:
        return None
    try:
        # 彩色 emoji（ttc / Noto Color）需要 index=0；ttf 不需要
        return ImageFont.truetype(p, size, index=0 if p.lower().endswith(".ttc") else 0)
    except Exception:
        try:
            return ImageFont.truetype(p, size)
        except Exception:
            return None


# 插件关键字 -> emoji 映射（按关键字命中，取第一个匹配）
PLUGIN_ICON_MAP = (
    ("天气", "🌤️"), ("预报", "🌤️"), ("气象", "🌤️"),
    ("签到", "✍️"), ("打卡", "✍️"), ("qb", "✍️"),
    ("翻译", "🌐"), ("translate", "🌐"),
    ("壁纸", "🖼️"), ("图片", "🖼️"), ("美图", "🖼️"),
    ("新闻", "📰"), ("早报", "📰"), ("日报", "📰"),
    ("王者", "🎮"), ("战力", "🎮"), ("游戏", "🎮"),
    ("笑话", "😂"), ("段子", "😂"), ("搞笑", "😂"),
    ("点歌", "🎵"), ("音乐", "🎵"), ("听歌", "🎵"),
    ("搜歌", "🔍"), ("搜索", "🔍"), ("查询", "🔍"), ("搜", "🔍"),
    ("计算", "🧮"), ("汇率", "💱"), ("油价", "⛽"),
    ("快递", "📦"), ("物流", "📦"),
    ("菜谱", "🍳"), ("菜", "🍳"), ("吃啥", "🍳"),
    ("表情", "🎭"), ("头像", "👤"), ("头像", "🖼️"),
    ("美女", "👧"), ("美腿", "👧"), ("小姐姐", "👧"),
    ("菜单", "📋"), ("帮助", "💡"), ("help", "💡"),
    ("工具", "🛠"), ("设置", "⚙️"), ("管理", "⚙️"),
    ("小说", "📖"), ("阅读", "📖"),
    ("提醒", "⏰"), ("todo", "📝"), ("待办", "📝"),
    ("星座", "♈"), ("运势", "🔮"),
    ("红包", "🧧"), ("账单", "💰"), ("钱包", "💰"), ("米包", "💰"),
    ("账号", "👤"), ("账户", "👤"), ("登录", "🔑"),
    ("AI", "🤖"), ("机器人", "🤖"),
)
# 无匹配时按顺序循环的兜底图标
FALLBACK_ICONS = ("📦", "✨", "🔹", "▪", "◆", "▫")
TITLE_HINTS = {}


def plugin_icon(title, index):
    """根据插件标题返回 emoji 或符号。"""
    if title in TITLE_HINTS:
        return TITLE_HINTS[title]
    lower = title.lower()
    for key, icon in PLUGIN_ICON_MAP:
        if key.lower() in lower or key in title:
            TITLE_HINTS[title] = icon
            return icon
    icon = FALLBACK_ICONS[index % len(FALLBACK_ICONS)]
    TITLE_HINTS[title] = icon
    return icon


def _text(draw, xy, text, **kwargs):
    """兼容旧版 Pillow（无 anchor 参数）的画字封装。"""
    try:
        draw.text(xy, text, **kwargs)
    except TypeError:
        kwargs.pop("anchor", None)
        draw.text(xy, text, **kwargs)


def _measure(draw, text, font):
    try:
        l, t, r, b = draw.textbbox((0, 0), text, font=font)
        return r - l, b - t
    except Exception:
        return font.getsize(text)


def _truncate(text, font, max_w, draw):
    if _measure(draw, text, font)[0] <= max_w:
        return text
    keep = text
    while keep and _measure(draw, keep + "…", font)[0] > max_w:
        keep = keep[:-1]
    return keep + "…"


def _draw_noise_bg(img):
    """极淡噪点背景（参考图那种细密点）。"""
    w, h = img.size
    px = img.load()
    for _ in range(int(w * h * 0.0006)):
        x = _random.randint(0, w - 1)
        y = _random.randint(0, h - 1)
        px[x, y] = BG_NOISE_A if (_random.random() < 0.5) else BG_NOISE_B


def _draw_outer_card(draw, box):
    """外层圆角卡片（白底+极细描边）。"""
    try:
        draw.rounded_rectangle(box, radius=24, fill=CARD_FILL, outline=CARD_LINE, width=1)
    except Exception:
        draw.rectangle(box, fill=CARD_FILL, outline=CARD_LINE, width=1)


def _eq_width(text_w, total_w):
    """根据文本宽度算出"====="需要多长才能撑满到 total_w（两侧夹击）。"""
    eq = "=" * max(3, int((total_w - text_w - 40) / _measure(None, "=", None)[0] if False else 0))
    # 实际宽度后面用等宽策略填充：用 _measure("=" * N) 算
    return eq


def _draw_eq_title(draw, x_center, y, label, font, total_w, gap_each_side=24, max_each=7):
    """画"===== 标题 ====="风格的标题。每侧最多 max_each 个"="，避免撑满整行（参考图风格）。"""
    lw, lh = _measure(draw, label, font)
    # 直接取每侧固定 6 个 "="，简洁且贴近参考图风格
    eq = "=" * max_each
    eq_w = _measure(draw, eq, font)[0]
    eq_color = EQ_TXT
    # 左半
    _text(draw, (x_center - lw / 2 - gap_each_side - eq_w / 2, y),
          eq, fill=eq_color, font=font, anchor="lm")
    # 文本
    _text(draw, (x_center, y), label, fill=TITLE_TXT, font=font, anchor="mm")
    # 右半
    _text(draw, (x_center + lw / 2 + gap_each_side + eq_w / 2, y),
          eq, fill=eq_color, font=font, anchor="lm")


def _draw_footer_signature(draw, canvas_w, y, signature):
    """底部脚注：一条居中短"="线 + 右下小字签名。"""
    font_eq = get_best_font(18)
    font_sig = get_best_font(16)
    eq = "=" * 22  # 短分割线，参考图风格
    _text(draw, (canvas_w // 2, y), eq, fill=EQ_TXT, font=font_eq, anchor="mm")
    _text(draw, (canvas_w - 50, y + 30), signature,
          fill=FOOT_TXT, font=font_sig, anchor="rm")


def _draw_emoji(draw, xy, icon, size, anchor="lm"):
    """画 emoji：有系统 emoji 字体用之，否则降级为符号（用主字体画）。"""
    font_emoji = _emoji_font(size)
    if font_emoji is not None:
        _text(draw, xy, icon, fill=BODY_TXT, font=font_emoji, anchor=anchor)
    else:
        # 降级：取 icon 的第一个非 emoji 字符作为符号备用
        # 优先尝试内置字体里有的符号 ▫ ★ ▶ → 等
        fallback = "▫"
        if icon not in ("📦", "✨", "🔹"):
            fallback = "◆" if "💎" in icon else "▫"
        _text(draw, xy, fallback, fill=BODY_TXT, font=get_best_font(int(size * 0.85)), anchor=anchor)


def draw_list_card(plugins):
    """第一级：插件列表卡片（v5.2 极简风格）。"""
    canvas_w = 1100
    margin = 40
    row_h = 78
    row_gap = 6
    pad_x = 50

    font_title = get_best_font(34)
    font_sub   = get_best_font(22)
    font_row   = get_best_font(32)
    font_cnt   = get_best_font(22)
    font_eq    = get_best_font(20)
    font_sig   = get_best_font(16)

    content_h = row_h * len(plugins) + row_gap * max(0, len(plugins) - 1)
    # 高度 = 顶部标题区 + 副标题 + 内容 + 底部脚注
    top_h = 60 + 38 + 28           # "=====" + 标题 + 副标题
    bottom_h = 50                  # "=====" + 脚注
    canvas_h = 40 + top_h + 24 + content_h + 32 + bottom_h + 28

    img = Image.new("RGB", (canvas_w, canvas_h), BG)
    _draw_noise_bg(img)
    draw = ImageDraw.Draw(img)

    # 外层卡片
    _draw_outer_card(draw, [20, 20, canvas_w - 20, canvas_h - 20])

    # 顶部标题"===== 标题 ====="
    title = config("title", "主人，请选择功能")
    _draw_eq_title(draw, canvas_w // 2, 60, title, font_eq, canvas_w - 80)
    # 副标题
    subtitle = f"共 {len(plugins)} 个功能 · 回复序号查看指令详情"
    _text(draw, (canvas_w // 2, 60 + 38 + 12), subtitle,
          fill=SUB_TXT, font=font_sub, anchor="mm")

    # 列表行
    list_y = 40 + top_h + 24
    for index, plugin in enumerate(plugins, 1):
        y = list_y + (index - 1) * (row_h + row_gap)
        # 行间分隔线（极浅）
        if index > 1:
            draw.line([(margin + pad_x, y - row_gap // 2),
                       (canvas_w - margin - pad_x, y - row_gap // 2)],
                      fill=ROW_DIVIDER, width=1)
        # emoji
        icon = plugin_icon(plugin["title"], index)
        _draw_emoji(draw, (margin + pad_x + 8, y + row_h // 2), icon, 32, anchor="lm")
        # 序号（灰字小号，紧跟 emoji）
        num_x = margin + pad_x + 62
        _text(draw, (num_x, y + row_h // 2), f"{index}.",
              fill=SUB_TXT, font=font_cnt, anchor="lm")
        # 插件名
        text_x = num_x + 36
        text_max_w = canvas_w - margin - pad_x - text_x - 160
        ptitle = _truncate(plugin["title"], font_row, text_max_w, draw)
        _text(draw, (text_x, y + row_h // 2), ptitle, fill=BODY_TXT, font=font_row, anchor="lm")
        # 右侧指令数
        cnt = len(plugin.get("commands") or [])
        cnt_text = f"{cnt} 条指令"
        _text(draw, (canvas_w - margin - pad_x, y + row_h // 2),
              cnt_text, fill=COUNT_TXT, font=font_cnt, anchor="rm")

    # 底部"=====" + 右下脚注
    footer_y = list_y + content_h + 32
    _draw_footer_signature(draw, canvas_w, footer_y, "© 2026 By 遇治菜")

    buf = BytesIO()
    img.save(buf, format="PNG", optimize=True)
    return f"base64://{base64.b64encode(buf.getvalue()).decode('utf-8')}"


def draw_detail_card(plugin):
    """第二级：单个插件指令详情卡片（v5.2 极简风格）。"""
    canvas_w = 1100
    margin = 40
    row_h = 64
    row_gap = 6
    pad_x = 50

    commands = plugin.get("commands") or []
    font_title = get_best_font(34)
    font_sub   = get_best_font(22)
    font_row   = get_best_font(30)
    font_empty = get_best_font(24)
    font_eq    = get_best_font(20)
    font_sig   = get_best_font(16)

    if commands:
        content_h = row_h * len(commands) + row_gap * max(0, len(commands) - 1)
    else:
        content_h = 80
    top_h = 60 + 38 + 28
    bottom_h = 50
    canvas_h = 40 + top_h + 24 + content_h + 32 + bottom_h + 28

    img = Image.new("RGB", (canvas_w, canvas_h), BG)
    _draw_noise_bg(img)
    draw = ImageDraw.Draw(img)

    _draw_outer_card(draw, [20, 20, canvas_w - 20, canvas_h - 20])

    title = plugin["title"]
    _draw_eq_title(draw, canvas_w // 2, 60, title, font_eq, canvas_w - 80)
    subtitle = f"共 {len(commands)} 条指令 · 发送对应指令即可使用"
    _text(draw, (canvas_w // 2, 60 + 38 + 12), subtitle,
          fill=SUB_TXT, font=font_sub, anchor="mm")

    list_y = 40 + top_h + 24

    if not commands:
        _text(draw, (canvas_w // 2, list_y + 40), "（该插件暂无指令可展示）",
              fill=SUB_TXT, font=font_empty, anchor="mm")
    else:
        for i, cmd in enumerate(commands, 1):
            y = list_y + (i - 1) * (row_h + row_gap)
            if i > 1:
                draw.line([(margin + pad_x, y - row_gap // 2),
                           (canvas_w - margin - pad_x, y - row_gap // 2)],
                          fill=ROW_DIVIDER, width=1)
            # emoji
            icon = plugin_icon(cmd, i)
            _draw_emoji(draw, (margin + pad_x + 8, y + row_h // 2), icon, 30, anchor="lm")
            # 指令文本
            tx = margin + pad_x + 60
            max_w = canvas_w - margin - pad_x - tx - 24
            cmd_text = _truncate(cmd, font_row, max_w, draw)
            _text(draw, (tx, y + row_h // 2), cmd_text, fill=BODY_TXT, font=font_row, anchor="lm")

    footer_y = list_y + content_h + 32
    _draw_footer_signature(draw, canvas_w, footer_y, "© 2026 By 遇治菜")

    buf = BytesIO()
    img.save(buf, format="PNG", optimize=True)
    return f"base64://{base64.b64encode(buf.getvalue()).decode('utf-8')}"


def send_image(base64_str):
    img_fn = getattr(sender, "replyImage", None)
    if callable(img_fn):
        try:
            img_fn(base64_str)
            return
        except Exception:
            pass
    sender.reply(f"[CQ:image,file={base64_str}]")


# ================== 两级菜单交互（复用 v2） ==================

def current_message():
    try:
        return str(sender.getMessage()).strip()
    except Exception:
        return ""


def has_wait():
    return any(callable(getattr(sender, name, None)) for name in ("input", "listen"))


def safe_listen(timeout_ms):
    candidates = (("input", (timeout_ms, 0, False)), ("listen", (timeout_ms,)))
    for name, args in candidates:
        fn = getattr(sender, name, None)
        if not callable(fn):
            continue
        try:
            text = str(fn(*args)).strip()
            return "" if text.lower() in ("", "timeout", "none", "null", "false") else text
        except Exception:
            continue
    return ""


def parse_index(text, count):
    if not text:
        return None
    match = re.search(r"(\d+)", text)
    if not match:
        return None
    index = int(match.group(1))
    return index if 1 <= index <= count else 0


def show_plugin_list(plugins):
    try:
        send_image(draw_list_card(plugins))
        return
    except Exception:
        pass
    lines = [f"====={config('title', '主人，请选择功能')}====="]
    for i, p in enumerate(plugins, 1):
        lines.append(f"\n[{i}] {p['title']}")
    lines.extend(["\n------------------", "回复序号查看对应指令", "或发送「菜单 序号」直达", "=================="])
    sender.reply("\n".join(lines))


def show_plugin_detail(plugin):
    try:
        send_image(draw_detail_card(plugin))
        return
    except Exception:
        pass
    lines = [f"====={plugin['title']}====="]
    cmds = plugin.get("commands") or []
    if cmds:
        lines.extend(f"  ▫️ {c}" for c in cmds)
    else:
        lines.append("  （该插件暂无指令可展示）")
    lines.extend(["\n------------------", config("footer", "发送对应指令即可使用"), "=================="])
    sender.reply("\n".join(lines))


# ================== 主入口 ==================

def main():
    plugins = scan_plugins()
    if not plugins:
        sender.reply("❌ 未扫描到可展示的插件")
        return
    count = len(plugins)

    msg = current_message()
    index = parse_index(msg, count)
    if index:
        show_plugin_detail(plugins[index - 1])
        return
    if index == 0:
        sender.reply(f"❌ 序号无效，请输入 1-{count} 之间的数字")
        return

    show_plugin_list(plugins)

    if not has_wait():
        sender.reply("⏰ 当前面板不支持交互等待，请直接发送「菜单 序号」查看插件指令")
        return
    timeout = config_int("timeout", 30)
    reply = safe_listen(timeout * 1000)
    if not reply:
        sender.reply(f"⏰ 选择超时（{timeout} 秒），请重新发送「菜单」")
        return
    index = parse_index(reply, count)
    if index:
        show_plugin_detail(plugins[index - 1])
    else:
        sender.reply(f"❌ 序号无效，请输入 1-{count} 之间的数字")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        sender.reply(f"❌ 菜单生成失败: {str(exc)}")
